if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$first=post_string('first_name',80);$last=post_string('last_name',80);$email=strtolower(post_string('email',190));$phone=post_string('phone',30);
 if(!$first||!$last||!filter_var($email,FILTER_VALIDATE_EMAIL))$err='Enter your first name, last name, and a valid email address.';
 else{$q=db()->prepare('SELECT id FROM users WHERE email=? AND id<>?');$q->execute([$email,$u['id']]);if($q->fetchColumn())$err='That email address is already in use.';else{$emailChanged=strtolower((string)$profile['email'])!==$email;db()->prepare('UPDATE users SET first_name=?,last_name=?,email=?,email_verified_at=IF(?,NULL,email_verified_at),phone=?,profile_complete=1 WHERE id=?')->execute([$first,$last,$email,$emailChanged?1:0,$phone?:null,$u['id']]);$_SESSION['user']['first_name']=$first;$_SESSION['user']['last_name']=$last;$_SESSION['user']['email']=$email;$_SESSION['user']['phone']=$phone;$_SESSION['user']['profile_complete']=1;if($emailChanged)$_SESSION['user']['email_verified_at']=null;audit('supervisor_profile_completed','user',(int)$u['id'],'Supervisor completed their profile');$needsVerification=$emailChanged||empty($profile['email_verified_at']);$mailSent=$needsVerification?issue_email_verification((int)$u['id'],$email,trim($first.' '.$last)):true;flash('success','Your supervisor profile is complete.');if($needsVerification)flash($mailSent?'info':'warning',$mailSent?'A verification link was sent to your email address.':'Email verification could not be sent. The system administrator needs to configure SMTP email.');redirect('supervisor/dashboard.php');}}
}
